import{_ as t,o as a,c as n,ak as r}from"./chunks/framework.B8jO0odJ.js";const m=JSON.parse('{"title":"App flow — Chainy","description":"Approved scope supersession — October 8, 2026: The user selected essential fundamentals for ages 12–17, especially underserved/remote learners with limited technology access, ","frontmatter":{"title":"App flow — Chainy","description":"Approved scope supersession — October 8, 2026: The user selected essential fundamentals for ages 12–17, especially underserved/remote learners with limited technology access, ","source":"docs/design/app-flow.md","category":"Game & system design","sourceUpdated":null,"outline":[2,3]},"headers":[],"relativePath":"content/docs/design/app-flow.md","filePath":"content/docs/design/app-flow.md"}'),i={name:"content/docs/design/app-flow.md"};function s(o,e,d,c,l,p){return a(),n("div",null,[...e[0]||(e[0]=[r(`<div><h1 id="app-flow--chainy">App flow — Chainy<a class="header-anchor" href="#app-flow--chainy" aria-label="Link to this section">​</a></h1><p><strong>Approved scope supersession — October 8, 2026:</strong> The user selected essential fundamentals for ages 12–17, especially underserved/remote learners with limited technology access, through tappable Web3, Blockchain and AI worlds. Full A–Z coverage is withdrawn. Free spatial construction and mandatory walkable 3D/joystick navigation are deferred; use bounded order/link activities, guided three-local-replica comparison, a genuine tiny classifier validated before production, and a short fixed-grid agent. The nine lesson IDs W1–W3, B1–B3 and A1–A3 are a draft curriculum, not a confirmed count. Current baseline/GDD/curriculum take precedence over historical issue titles and old level IDs below. Phone specifications, SQLite/export, rubric and November 21 deadline remain. The old 520-hour estimate has not been recosted for this scope.</p><p>Version 0.1 • October 8, 2026 • Proposed interaction/state contract. Required concepts follow the <a href="/Chainy-Docs/content/docs/project-baseline.html">baseline</a> and <a href="/Chainy-Docs/content/docs/game-design.html">GDD</a>. This flow does not establish implementation or pilot evidence. “Background schema” means the <a href="/Chainy-Docs/content/docs/design/database-schema.html">SQLite database schema</a>, as clarified by the user.</p><h2 id="learner-journey">Learner journey<a class="header-anchor" href="#learner-journey" aria-label="Link to this section">​</a></h2><figure class="diagram"><div class="mermaid-source"><pre>flowchart TD
  Boot[Bootstrap: content and database validation] --&gt;|ready| Profile[Learner code / local profile]
  Boot --&gt;|cannot safely open| Recover[Recovery instructions; preserve data]
  Profile --&gt;|existing code| Menu[Main menu]
  Profile --&gt;|unknown valid code| Confirm[Confirm new local profile]
  Confirm --&gt;|create| Menu
  Confirm --&gt;|cancel| Profile
  Menu --&gt; Map[Map: Web3 / Blockchain / AI worlds]
  Map --&gt; Lessons[Lesson cards in chosen world]
  Lessons --&gt;|available| Brief[Short lesson introduction]
  Brief --&gt; Explore[Guided explanation and example]
  Explore --&gt; Work[Bounded learning activity]
  Work --&gt;|test| Feedback[Rule feedback]
  Feedback --&gt;|revise| Work
  Feedback --&gt;|activity satisfied| Quiz[Formative quiz]
  Quiz --&gt; Save[Commit attempt and progress]
  Save --&gt;|failure| RetrySave[Retry same submission / safe recovery]
  RetrySave --&gt; Save
  Save --&gt;|committed, incomplete| Quiz
  Save --&gt;|committed, complete| Summary[Summary and badge]
  Summary --&gt; Map
  Menu --&gt; Staff[Staff export workflow]
</pre></div><figcaption><span>Diagram</span><button class="diagram-fullscreen">Full screen ↗</button><button class="diagram-expand" aria-expanded="false">Expand diagram</button><a href="#" class="diagram-toggle">Show source</a></figcaption></figure><p>The diagram omits pause links for readability; every active learning screen obeys the transition table below. Proposed quiz length and unlock threshold are GDD tuning choices, not school assessment rules. A wrong answer receives explanatory feedback and a deliberate retry; it does not silently become a correct historical answer.</p><h2 id="state-and-transition-contract">State and transition contract<a class="header-anchor" href="#state-and-transition-contract" aria-label="Link to this section">​</a></h2><table><thead><tr><th>State</th><th>Entry / visible actions</th><th>Transition guard and data effect</th><th>Failure/recovery</th></tr></thead><tbody><tr><td>Bootstrap</td><td>Validate bundled content; open supported schema</td><td>Ready only when migrations and integrity checks complete</td><td>Unsupported/corrupt/migration failure → recovery; never silently delete/reset DB</td></tr><tr><td>Profile entry</td><td>Enter study and learner code; help</td><td>Normalize proposed code format; existing key selects profile; unknown code needs explicit creation confirmation</td><td>Invalid format explains correction; valid typo cannot be distinguished from a new code, so warn</td></tr><tr><td>Main menu</td><td>Continue, map, settings, switch learner, staff mode</td><td>Continue resolves latest valid checkpoint for selected profile</td><td>No checkpoint → briefing; incompatible checkpoint → explained safe restart, preserve historical evidence</td></tr><tr><td>Map / lesson cards</td><td>Web3, Blockchain and AI entries; lesson objectives and saved progress</td><td>Lesson prerequisites come from versioned content; replay starts a new session</td><td>Explain unavailable lesson prerequisites; no hard-coded three-level count</td></tr><tr><td>Briefing</td><td>Short objective/instructions; begin/back</td><td>Begin creates active session with immutable app/content versions before evidence collection</td><td>Failed session creation blocks attempt start and offers retry</td></tr><tr><td>Guided lesson</td><td>Read short explanation, inspect example, begin activity, pause</td><td>Open bounded activity with same session/context; no walkable scene prerequisite</td><td>Missing content returns safely to lesson list; explain unknown ID</td></tr><tr><td>Order/link activity</td><td>Select/reorder supplied records, select predecessor, test, revise/reset</td><td>Validate causal order and links from bounded choices</td><td>Explain invalid order/link; confirmed reset preserves history</td></tr><tr><td>Ledger/node activity</td><td>Inspect, alter test data, validate, preview repair</td><td>Specific rule feedback; reconciliation is explicit learner action</td><td>No agreement remains a learnable state; never arbitrary repair</td></tr><tr><td>Classifier activity</td><td>Label examples, train, test held-out items, inspect errors</td><td>Train only with valid feature schema and examples for required classes</td><td>Missing class or tied result shown; never silently invent prediction certainty</td></tr><tr><td>Agent activity</td><td>Edit policy, step/run/stop/reset; trace</td><td>Fixed environment and capped step count; completion requires defined delivery goal</td><td>Invalid action/loop → explanation and edit; stop leaves editable policy</td></tr><tr><td>Feedback</td><td>Explanation, hint, retry or proceed</td><td>Proceed requires activity completion rule; hints/retries attached to meaningful attempt</td><td>Wrong result is preserved if evidence is in approved scope; no all-progress reset</td></tr><tr><td>Quiz</td><td>Read, select answer, submit, explanation</td><td>Disable duplicate submit; generate stable event once; submit transaction records outcome</td><td>Failed save keeps pending submission; retry same ID; deliberate new answer uses new ID</td></tr><tr><td>Persisting</td><td>Visible saving state; no double submission</td><td>Commit attempt/checkpoint/completion atomically; completion only after commit</td><td>No success badge until commit; storage-full/busy path explains recoverable action</td></tr><tr><td>Summary</td><td>Result, explanation, earned badge, map</td><td>Display persisted state; replay creates new attempt/session and retains first result</td><td>Reload committed state after interrupted rendering</td></tr><tr><td>Pause/settings</td><td>Resume, audio/text controls, return to map, switch learner</td><td>Commit safe checkpoint before leaving; interrupt unfinished session on confirmed exit</td><td>If save fails, explain possible loss of uncommitted edits; stay/retry or explicitly leave</td></tr><tr><td>Recovery</td><td>Explain issue, retry, staff recovery guidance</td><td>Preserve old DB/export; use supported recovery procedure</td><td>No automatic destructive reset, no claim learner code restores lost data</td></tr></tbody></table><h2 id="session-retry-and-shared-device-rules">Session, retry and shared-device rules<a class="header-anchor" href="#session-retry-and-shared-device-rules" aria-label="Link to this section">​</a></h2><p>A profile is <code>(study_id, learner_code)</code>; device installation ID is supplementary. A new session begins when a mission starts or resumes after interruption. Returning to map closes the session as completed only when its intended activity flow completed; otherwise interrupted. Choosing another learner confirms departure, persists a safe checkpoint, closes the current session and clears in-memory profile data before profile entry.</p><p>Android suspend requests a safe checkpoint but cannot be the only save trigger. Resume in the same surviving process continues the session. Restart after process death marks prior active sessions interrupted and starts a fresh session when the learner continues. No incomplete session is converted into a passing result. Durable checkpoints cover logical state, not transient animations.</p><p>Distinguish “retry save” from “retry activity”: retry save reuses an event ID; deliberate new activity/quiz attempts generate new IDs and increment retry counts. First answers remain recoverable from immutable events. Badges and unlocks derive from committed completion under versioned content rules.</p><h2 id="staff-export-and-receipt-journey">Staff export and receipt journey<a class="header-anchor" href="#staff-export-and-receipt-journey" aria-label="Link to this section">​</a></h2><figure class="diagram"><div class="mermaid-source"><pre>flowchart LR
  Scope[Staff selects approved study/session scope] --&gt; Preview[Record count and destination explanation]
  Preview --&gt; Snapshot[Consistent logical snapshot and manifest]
  Snapshot --&gt; Picker[Android save picker]
  Picker --&gt;|cancel or failure| Keep[Keep all local evidence; retry available]
  Picker --&gt;|write verified| Written[File saved: receipt still pending]
  Written --&gt; Transfer[Teacher transfers using approved route]
  Transfer --&gt; Import[Staff importer validates and deduplicates]
  Import --&gt; Receipt[Accepted / duplicate / rejected counts]
  Receipt --&gt; Confirm[Record receipt against export ID]
</pre></div><figcaption><span>Diagram</span><button class="diagram-fullscreen">Full screen ↗</button><button class="diagram-expand" aria-expanded="false">Expand diagram</button><a href="#" class="diagram-toggle">Show source</a></figcaption></figure><p>Staff navigation is deliberately separate from learner play. A staff menu/PIN, if chosen, is a convenience control; custody and approved access procedures protect research records. Preview shows scope/count and makes no automatic-upload claim. Avoid exposing a roster to learners. Export scope and permissible fields must match the approved study protocol.</p><p>A saved file is not proof of transfer. Importer rejection or partial rejection remains an actionable staff state; it must not mark the whole batch received or delete local records. If receipt entry is manual, staff records its identifier only after reviewing counts. The exact receipt-entry UI and transfer route remain decisions for CH-04/11/12. Uninstalling the app is not an export or backup procedure.</p><h2 id="accessibility-and-navigation-acceptance">Accessibility and navigation acceptance<a class="header-anchor" href="#accessibility-and-navigation-acceptance" aria-label="Link to this section">​</a></h2><p>Every outcome combines readable text with any color/icon/audio. Touch selection buttons supplement precise dragging. Tappable world/lesson navigation and clearly labeled activity actions avoid competing gestures; a movement joystick is not required. Confirm destructive workbench reset and profile switching; routine retry stays quick. Check Android back navigation on each modal, picker and activity so it returns to the intended parent state without bypassing saving or duplicating submissions.</p><p>Flow checks: fresh profile → first agreed lesson completion; existing profile → resume; locked level; valid-format typo → cancel new profile; switch between two profiles; bad order/link → correction; classifier missing-class/tie; agent step limit; double submit; failed commit; process termination before/after commit; canceled export; repeated export/import; incompatible checkpoint; signed update. Record actual results in issue evidence and the QA record, not as assumed outcomes here.</p><h2 id="implementation-handoff">Implementation handoff<a class="header-anchor" href="#implementation-handoff" aria-label="Link to this section">​</a></h2><p>Miguel owns learner/staff UI; Christian owns lifecycle, persistence and integration; Sherwin owns AI behavior and external import; Sean reviews wording and study evidence semantics. Agents can build independent panels and pure services against these contracts, but the integration owner merges navigation/scene composition. See <a href="/Chainy-Docs/content/docs/requirements/technical-requirements.html">technical requirements</a> for acceptance contracts and <a href="/Chainy-Docs/content/docs/kanban-plan-draft.html">active plan</a> for authoritative issue links. Protect integration, QA and rehearsal before November 21, 2026.</p><p>Parallel work ownership, contract gates and review packets are defined in the <a href="/Chainy-Docs/content/docs/planning/implementation-plan.html">implementation plan</a>.</p><h2 id="revised-lesson-catalog-and-resume-guards">Revised lesson catalog and resume guards<a class="header-anchor" href="#revised-lesson-catalog-and-resume-guards" aria-label="Link to this section">​</a></h2><p>Use content-defined lesson IDs and world membership, with draft W1–W3/B1–B3/A1–A3 only until curriculum review. Continue resolves the selected profile and saved content version before opening a lesson. Legacy L1/L2/L3 checkpoints require the explicit version mapping in the database contract; never infer a new lesson pass from a renamed old level. Unsupported checkpoints offer an explained safe restart and retain historical attempts. All three worlds must be visible; lesson prerequisites/unlocks are proposed content rules, not a hard-coded three-level sequence.</p><p>Proposed initial access policy, aligned with the GDD: all three world entry lessons W1, B1 and A1 are available; later lessons follow prerequisites within their own world; completed lessons replay. The W1-through-A3 teaching sequence is a suggested learning route, not a global lock. Freeze actual prerequisites with the final lesson catalog in CH-02.</p></div>`,1)])])}const h=t(i,[["render",s]]);export{m as __pageData,h as default};
